//! OpenMLS storage with change tracking.
//!
//! GENERATED by `scripts/vendor-mls-store.py` from openmls_memory_storage
//! 0.6.0 (Copyright (c) 2019 OpenMLS Authors, MIT License). Do not edit by
//! hand; change the script and regenerate.
//!
//! All OpenMLS state lives in one ordered in-memory map. Every key a step
//! writes or deletes is recorded, so the step can return exactly its changes
//! as a single batch that the driver persists atomically before acting.
//!
//! Values are postcard behind a tag byte ([`encode`]); OpenMLS rewrites its
//! whole ratchet tree on every commit, and JSON spells each byte as a number.
//! Values from before (JSON) are still read ([`decode`]), and keys stay JSON
//! so those records are found. Reading a damaged value is an error.
#![allow(clippy::unwrap_used, clippy::all)]

use openmls_traits::storage::*;
use serde::Serialize;
use std::collections::{BTreeMap, BTreeSet};
use std::sync::RwLock;


/// A storage for the V_TEST version.


#[derive(Debug, Default)]
pub struct MlsStore {
    values: RwLock<Tracked>,
}

// For testing we want to clone.

// For testing (KATs in particular) we want to serialize and deserialize the storage

impl MlsStore {
    /// Internal helper to abstract write operations.
    #[inline(always)]
    fn write<const VERSION: u16>(
        &self,
        label: &[u8],
        key: &[u8],
        value: Vec<u8>,
    ) -> Result<(), <Self as StorageProvider<CURRENT_VERSION>>::Error> {
        let mut values = self.values.write().unwrap();
        let storage_key = build_key_from_vec::<VERSION>(label, key.to_vec());


        values.insert(storage_key, value.to_vec());
        Ok(())
    }

    fn append<const VERSION: u16>(
        &self,
        label: &[u8],
        key: &[u8],
        value: Vec<u8>,
    ) -> Result<(), <Self as StorageProvider<CURRENT_VERSION>>::Error> {
        let mut values = self.values.write().unwrap();
        let storage_key = build_key_from_vec::<VERSION>(label, key.to_vec());


        // fetch value from db, falling back to an empty list if doens't exist
        let mut list: Vec<Vec<u8>> = match values.get(&storage_key) {
            Some(list_bytes) => decode(list_bytes)?,
            None => Vec::new(),
        };
        list.push(value);
        values.insert(storage_key, encode(&list)?);

        Ok(())
    }

    fn remove_item<const VERSION: u16>(
        &self,
        label: &[u8],
        key: &[u8],
        value: Vec<u8>,
        json: Vec<u8>,
    ) -> Result<(), <Self as StorageProvider<CURRENT_VERSION>>::Error> {
        let mut values = self.values.write().unwrap();
        let storage_key = build_key_from_vec::<VERSION>(label, key.to_vec());


        // fetch value from db, falling back to an empty list if doens't exist
        let mut list: Vec<Vec<u8>> = match values.get(&storage_key) {
            Some(list_bytes) => decode(list_bytes)?,
            None => Vec::new(),
        };
        if let Some(pos) = list
            .iter()
            .position(|stored_item| *stored_item == value || *stored_item == json)
        {
            list.remove(pos);
        }
        values.insert(storage_key, encode(&list)?);

        Ok(())
    }

    /// Internal helper to abstract read operations.
    #[inline(always)]
    fn read<const VERSION: u16, V: Entity<VERSION>>(
        &self,
        label: &[u8],
        key: &[u8],
    ) -> Result<Option<V>, <Self as StorageProvider<CURRENT_VERSION>>::Error> {
        let values = self.values.read().unwrap();
        let storage_key = build_key_from_vec::<VERSION>(label, key.to_vec());


        let value = values.get(&storage_key);

        if let Some(value) = value {
            decode(value).map(Some)
        } else {
            Ok(None)
        }
    }

    /// Internal helper to abstract read operations.
    #[inline(always)]
    fn read_list<const VERSION: u16, V: Entity<VERSION>>(
        &self,
        label: &[u8],
        key: &[u8],
    ) -> Result<Vec<V>, <Self as StorageProvider<CURRENT_VERSION>>::Error> {
        let values = self.values.read().unwrap();

        let mut storage_key = label.to_vec();
        storage_key.extend_from_slice(key);
        storage_key.extend_from_slice(&u16::to_be_bytes(VERSION));


        let value: Vec<Vec<u8>> = match values.get(&storage_key) {
            Some(list_bytes) => decode(list_bytes)?,
            None => vec![],
        };

        value
            .iter()
            .map(|value_bytes| decode(value_bytes))
            .collect::<Result<Vec<V>, _>>()
            .map_err(|_| MlsStoreError::SerializationError)
    }

    /// Internal helper to abstract delete operations.
    #[inline(always)]
    fn delete<const VERSION: u16>(
        &self,
        label: &[u8],
        key: &[u8],
    ) -> Result<(), <Self as StorageProvider<CURRENT_VERSION>>::Error> {
        let mut values = self.values.write().unwrap();

        let mut storage_key = label.to_vec();
        storage_key.extend_from_slice(key);
        storage_key.extend_from_slice(&u16::to_be_bytes(VERSION));


        values.remove(&storage_key);

        Ok(())
    }
}

/// Errors thrown by the key store.
#[derive(thiserror::Error, Debug, Copy, Clone, PartialEq, Eq)]
pub enum MlsStoreError {
    #[error("The key store does not allow storing serialized values.")]
    UnsupportedValueTypeBytes,
    #[error("Updating is not supported by this key store.")]
    UnsupportedMethod,
    #[error("Error serializing value.")]
    SerializationError,
}

